        /* sdd-asis-lifecycle:begin ipt_listAmt_onkeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        (($c.util.getComponent('txt_listAmtHanview') && $c.util.getComponent('txt_listAmtHanview').setValue) ? $c.util.getComponent('txt_listAmtHanview').setValue($c.num.formatNumberKor(String((((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar))))) == null ? '' : (((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar)))))).replace(/,/g, ''))) : console.warn('[sdd] num2won 대상 미해결: ' + 'list_amt_hanview'));
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf15300.ipt_listAmt_onkeyup' }); }
};

