// 표준 API 조합으로 새로 작성한 검사 함수
/**
 * @method
 * @name scwin.CheckReqInfo_Cellphone
 * @author Inswave
 * @date 2026. 09. 29
 * @param fm
 * @returns
 * @hidden N
*/
scwin.CheckReqInfo_Cellphone = async function (fm) { try { const v = (fm && fm.getValue) ? fm.getValue() : (fm && fm.value != null ? fm.value : null); if (v == null || String(v) === '') { return true; } if (!$c.str.isMobilePhone(String(v))) { await $c.win.alert('휴대전화번호 형식을 확인해 주세요.'); return false; } return true; } catch (_e) { return true; } };

/**
 * @method
 * @name scwin.mpd_files_selectCallback
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_objInstNm').getValue()) == 0) {
        await $c.win.alert("피종목분할 대상기관을 선택하십시오.");
        $c.util.getComponent("ipt_objInstNm").focus();
        return;
    } else {
        if ($c.util.getComponent("dma_searchReq").get("objInstCd") === $c.util.getComponent("dma_searchReq").get("isurCd")) {
            await $c.win.alert("피종목분할 대상기관으로 해당 발행기관을 선택할 수 없습니다.");
            $c.util.getComponent("dma_searchReq").set("objInstCd", "");
            $c.util.getComponent("ipt_objInstNm").setValue("");
            $c.util.getComponent("ipt_objInstNm").focus();
            return;
        }
    }
    fm.action = '/company/company.do?method=searchBndListBySplitMerge&pageDiv=split';
    await scwin.tx_fn_search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.initSplitMergeApplPop
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIdx rownum
 * @returns
 * @hidden N
*/
scwin.initSplitMergeApplPop = function (rowIdx, rownum) {
    /* sdd-asis-lifecycle:begin fn_initSplitMergeApplPop — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    if (rownum == 1) {
        $c.util.getComponent("ipt_bfchgIsuNm").setValue($c.util.getComponent('dlt_result').getCellData(0, 'orgIsuNm'));
        $c.util.getComponent("ipt_bfchgIsuEngNm").setValue($c.util.getComponent("dma_searchReq").get("orgIsuEngNm"));
        $c.util.getComponent("ipt_bfchgListAmt").setValue($c.util.getComponent("dma_searchReq").get("orgListAmt"));
        $c.util.getComponent("dma_searchReq").set("bfchgStdCd", $c.util.getComponent("dma_searchReq").get("orgStdCd"));
    } else {
        if (rownum > 1) {
            $c.util.getComponent("ipt_bfchgIsuNm").setValue($c.util.getComponent('dlt_result').getCellData(rowIdx, 'orgIsuNm'));
            $c.util.getComponent("ipt_bfchgIsuEngNm").setValue(fm.org_isu_eng_nm[rowIdx].value);
            $c.util.getComponent("ipt_bfchgListAmt").setValue($c.util.getComponent('dlt_result').getCellData(rowIdx, 'orgListAmt'));
            $c.util.getComponent("dma_searchReq").set("bfchgStdCd", $c.util.getComponent('dlt_result').getCellData(rowIdx, 'orgStdCd'));
        }
    }
    $c.util.getComponent("ipt_applIsuNm").focus();
    $c.util.getComponent("dma_searchReq").set("rowIndex", rowIdx);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkData
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIdx
 * @returns
 * @hidden N
*/
scwin.checkData = async function (rowIdx) {
    /* sdd-asis-lifecycle:begin fn_checkData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    const _mktact_cd = $c.util.getComponent("dma_searchReq").get("bndMktactTpCd");
    const _now_time = dma_hiddenStore.get("areaNowTimer");
    const _isur_cd = $c.util.getComponent("dma_searchReq").get("isurCd");
    if (!applTmCheck(_mktact_cd, _now_time, _isur_cd)) {
        return false;
    }
    if (!$('#SendForm input[name="objInstNm"]').val()) {
        await $c.win.alert("피종목분할 대상기관을 선택하십시오.");
        return false;
    }
    if (!$('#SendForm input:radio[name="check"]:checked').val()) {
        await $c.win.alert("분할종목을 선택하십시오.");
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_procsReqDd').getValue()) == 0) {
        await $c.win.alert("적용희망일을 입력하십시오.");
        $c.util.getComponent("cal_procsReqDd").focus();
        return false;
    } else {
        if (WebSquare.date.getCurrentServerDate("yyyyMMdd") >= $c.util.getComponent('cal_procsReqDd').getValue().replace("-", "").replace("-", "")) {
            await $c.win.alert("적용희망일은 익일 이후만 입력가능합니다.");
            $c.util.getComponent("cal_procsReqDd").focus();
            return;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('cal_genmeetHldDd').getValue()) == 0) {
                await $c.win.alert("주주 임시총회일을 입력하십시오.");
                $c.util.getComponent("cal_genmeetHldDd").focus();
                return false;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('cal_rsnOccrDd').getValue()) == 0) {
                    await $c.win.alert("변경등기일을 입력하십시오.");
                    $c.util.getComponent("cal_rsnOccrDd").focus();
                    return false;
                } else {
                    if ($c.str.getByteLength($c.util.getComponent('ipt_applIsuNm').getValue()) == 0) {
                        await $c.win.alert("한글종목명을 입력하십시오.");
                        $c.util.getComponent("ipt_applIsuNm").focus();
                        return false;
                    } else {
                        if ($c.str.getByteLength($c.util.getComponent('ipt_applIsuEngNm').getValue()) == 0) {
                            await $c.win.alert("영문종목명을 입력하십시오.");
                            $c.util.getComponent("ipt_applIsuEngNm").focus();
                            return false;
                        } else {
                            if ($c.str.getByteLength($c.util.getComponent('ipt_splitRtoContn').getValue()) == 0) {
                                await $c.win.alert("분할비율을 확인하십시오.");
                                $c.util.getComponent("ipt_splitRtoContn").focus();
                                return false;
                            } else {
                                if (!Chk_Digit_Point($c.util.getComponent('ipt_splitRtoContn').getValue()) || $c.util.getComponent('ipt_splitRtoContn').getValue()>= 100) {
                                    await $c.win.alert("분할비율을 확인하십시오.");
                                    $c.util.getComponent("ipt_splitRtoContn").focus();
                                    return false;
                                } else {
                                    if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
                                        return false;
                                    } else {
                                        if ($c.str.getByteLength($c.util.getComponent('slc_bdchrgTpCd').getValue()) == 0) {
                                            return false;
                                        } else {
                                            if (!scwin.CheckReqInfo_Cellphone(fm)) {
                                                return false;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    /* sdd-asis-lifecycle:begin fn_save — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    var fm = (document.SendForm || { elements: [] });
    if (!await scwin.checkData($c.util.getComponent("dma_searchReq").get("rowIndex"))) {
        return;
    } else {
        if (!await $c.win.confirm("신청하시겠습니까?")) {
            return false;
        }
    }
    var fm = (document.SendForm || { elements: [] });
    fm.action = '/company/company.do?method=saveSplitAppl';
    await scwin.tx_fn_save();
    /* sdd-asis-lifecycle:end */
};


